// ================================================================
// قالب وصل/استمارة التبرع (A5 بالعرض — التصميم الأصلي A4 مصغّر 70%) — مأخوذ كما هو من receipt_EMPTY.html (التصميم والخطوط والجداول
// والإطار والشعار المدمج). يُطبع داخل iframe مخفي فيبقى CSS القالب معزولاً تماماً عن التطبيق.
// الباركود: نفس باركود التطبيق (CODE128 عبر JsBarcode، وقيمته رقم المتبرع) وليس مولّد القالب.
// ================================================================
// خط PT Bold Heading مضمّن (woff مُقلَّص للحروف العربية) حتى يُطبع على أي جهاز بدون تنصيب
const RECEIPT_FONT_B64 = '';
// خط DTP Naskh S محوَّل لدعم الحروف العربية العادية (يونيكود) ومضمّن لخانات البيانات
const RECEIPT_FONT2_B64 = '';
const RECEIPT_CSS = `@font-face{font-family:'DTP Naskh S';font-style:normal;font-weight:400;src:url(data:font/woff;base64,${RECEIPT_FONT2_B64}) format('woff')}@font-face{font-family:'PT Bold Heading';font-style:normal;font-weight:100 900;src:url(data:font/woff;base64,${RECEIPT_FONT_B64}) format('woff')}
*{box-sizing:border-box}body{margin:0;background:#ddd;font-family:Tahoma,Arial,sans-serif;color:#111;font-weight:700} @page{size:A5 landscape;margin:0}
.sheet{width:297mm;height:210mm;padding:9mm 12mm;background:white;margin:10mm auto}.frame{height:192mm;border:1.4mm solid #000;padding:7mm 9mm 3mm;position:relative}
.header{height:50.5mm;position:relative;text-align:center}.authority{position:absolute;right:0;top:4mm;width:76mm;white-space:nowrap;font-size:14.5pt;line-height:1.4}.heading{position:absolute;top:5.5mm;left:72mm;right:65mm;font-size:21pt;line-height:1.5;white-space:nowrap}.heading span{display:block;direction:ltr;font-size:18pt}.logo{position:absolute;left:0;top:0;width:38mm;height:32mm;object-fit:contain}.missing-logo{position:absolute;left:0;top:0;width:38mm;height:32mm;border:1px dashed #bbb;display:grid;place-content:center;color:#999;font-size:9pt}
.barcode{position:absolute;top:27.5mm;left:69mm;width:128mm;height:16mm;text-align:center}.barcode svg{width:124mm;height:10mm;display:block;margin:0 auto}.barcode small{font-size:11.5pt;display:block;line-height:1.2;margin-top:.5mm}
.bag{position:absolute;left:0;top:45.5mm;width:36mm;height:27mm;border:1mm solid #222;text-align:center;background:white;font-size:23pt;z-index:1}.bag div{height:13mm;display:grid;place-content:center}.bag div+div{border-top:.8mm solid #222;font-size:22pt;direction:ltr}
.data{width:100%;border-collapse:separate;border-spacing:0 2.5mm;margin-top:-1.2mm;table-layout:fixed;font-size:18pt}.data td{height:9.5mm;border:.2mm solid #e2e2e2;padding:0 2mm;text-align:center;vertical-align:middle}.data .label{background:#d5d5d5;font-size:17pt;white-space:nowrap;border-color:#d5d5d5}.ltr{direction:ltr;unicode-bidi:isolate}.data .empty{border:0}.data .section{height:9mm;font-size:18pt;background:#fff}.exam{width:100%;border-collapse:collapse;table-layout:fixed;font-size:16pt}.exam th{font-size:17pt;height:8.5mm;background:#d5d5d5;border:.2mm solid #e2e2e2}.exam td{height:13.6mm;text-align:center;border:.2mm solid #e2e2e2;font-size:18pt}.toolbar{text-align:center;margin:5mm;font-weight:400}.toolbar button{padding:10px 30px;font-size:16px}
.authority,.heading,.data .label,.data .section,.exam th{font-family:'PT Bold Heading',Tahoma,Arial,sans-serif;font-synthesis:none}.data .label,.data .section,.exam th{line-height:1.05}.data td:not(.label):not(.section),.exam td,.bag div{font-family:'DTP Naskh S',Tahoma,Arial,sans-serif;line-height:1.1}.heading span{font-family:Tahoma,Arial,sans-serif}
@media print{body{background:white}.sheet{margin:0}.toolbar{display:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
@media print{html,body{width:210mm;height:148mm;overflow:hidden}.sheet{break-inside:avoid;page-break-after:avoid;zoom:.7;margin:.5mm auto 0}}`;
const RECEIPT_MAIN = `<main class="sheet"><div class="frame"><header class="header">
<div class="authority">دائرة صحة واسط<br>مصرف الدم الرئيسي في واسط</div>
<div class="heading">استمارة التبرع بالدم ومشتقاته<span>Blood Donor Questionnaire</span></div>
<img class="logo" id="receiptLogo" alt="شعار وزارة الصحة العراقية" src="data:image/png;base64,">
<div class="barcode"><div id="barcode"></div><small class="ltr" data-field="barcodeValue"></small></div>
<div class="bag"><div data-field="donationProduct"></div><div data-field="bagNumber"></div></div>
</header>
<table class="data"><colgroup><col style="width:42mm"><col style="width:18mm"><col style="width:52mm"><col style="width:33mm"><col style="width:34.5mm"><col style="width:7.5mm"><col style="width:28.5mm"><col></colgroup><tbody>
<tr><td class="label">الاسم الرباعي:</td><td colspan="7" data-field="donorName"></td></tr>
<tr><td class="label">اسم الأم:</td><td colspan="5" data-field="motherName"></td><td class="label">رقم القنينة:</td><td class="empty"></td></tr>
<tr><td class="label" colspan="2" data-field="identityLabel">رقم البطاقة الوطنية:</td><td colspan="4" class="ltr" data-field="identityNumber"></td><td class="label">المهنة</td><td data-field="occupation"></td></tr>
<tr><td class="label">سنة التولد:</td><td colspan="2" class="ltr" data-field="birthYear"></td><td class="label">العمر:</td><td colspan="2" class="ltr" data-field="age"></td><td class="label">الجنس</td><td data-field="gender"></td></tr>
<tr><td class="label">رقم الموبايل:</td><td colspan="7" class="ltr" data-field="phone"></td></tr>
<tr><td class="label">عنوان السكن:</td><td colspan="7" data-field="address"></td></tr>
<tr><td class="label">نوع التبرع:</td><td colspan="2" data-field="donationType"></td><td class="label">تاريخ التبرع:</td><td colspan="3" class="ltr" data-field="donationDate"></td><td class="ltr" data-field="donationTime"></td></tr>
<tr><td class="label">اسم المريض:</td><td colspan="3" data-field="patientName"></td><td class="label" colspan="2">اسم المستشفى:</td><td colspan="2" data-field="hospitalName"></td></tr>
<tr><td colspan="4" class="section">صنف الدم والعامل الريسي</td><td colspan="4" class="empty"></td></tr></tbody></table>
<table class="exam"><thead><tr><th>ضغط الدم</th><th>النبض</th><th>درجة الحرارة</th><th>الوزن</th><th>الهيموكلوبين</th></tr></thead><tbody><tr><td class="ltr" data-field="bloodPressure"></td><td class="ltr" data-field="pulse"></td><td class="ltr" data-field="temperature"></td><td class="ltr" data-field="weight"></td><td class="ltr" data-field="hemoglobin"></td></tr></tbody></table>
</div></main>`;

// data: { barcodeValue, donationProduct, bagNumber, donorName, motherName, identityNumber, occupation,
//         identityLabel (optional, default رقم البطاقة الوطنية:), birthYear, age, gender, phone, address, donationType, donationDate, donationTime,
//         patientName, hospitalName, bloodPressure, pulse, temperature, weight, hemoglobin }
function buildReceiptHtml(data){
  const json = JSON.stringify(data||{}).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
  return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>استمارة التبرع بالدم ومشتقاته</title>'
  + '<script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.5/dist/JsBarcode.all.min.js"><\/script>'
  + '<style>' + RECEIPT_CSS + '</style></head><body>' + RECEIPT_MAIN
  + '<script>' + RECEIPT_SCRIPT.replace('__DATA__', function(){ return json; }) + '<\/script></body></html>';
}

const RECEIPT_SCRIPT = [
"// textContent prevents HTML injection.",
"function setReceiptData(data){data=data||{};document.querySelectorAll('[data-field]').forEach(function(el){var v=data[el.dataset.field];if(el.dataset.field==='identityLabel'&&!v)return;el.textContent=(v===undefined||v===null)?'':v});renderBarcode(String(data.barcodeValue===undefined||data.barcodeValue===null?'':data.barcodeValue));fitReceiptCells();}",
"function fitReceiptCells(){document.querySelectorAll('td[data-field],.bag div,.data .label,.data .section,.exam th').forEach(function(el){el.style.whiteSpace='nowrap';var cs=getComputedStyle(el);var avail=el.clientWidth-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight)-2;var fs=parseFloat(cs.fontSize);var r=document.createRange();r.selectNodeContents(el);var n=0;while(r.getBoundingClientRect().width>avail&&fs>11&&n<60){fs-=0.5;el.style.fontSize=fs+'px';n++;}});}",
"function setReceiptLogo(src){document.getElementById('receiptLogo').src=src;}",
"// The app's own barcode: CODE128 via JsBarcode (same library, format and value the app already used).",
"function renderBarcode(value){",
"  var target=document.getElementById('barcode'); target.innerHTML='';",
"  if(!value) return;",
"  var JB=window.JsBarcode||(window.parent&&window.parent.JsBarcode); if(!JB) return;",
"  var svg=document.createElementNS('http://www.w3.org/2000/svg','svg');",
"  try{ JB(svg,value,{format:'CODE128',displayValue:false,height:40,width:2,margin:0}); }catch(e){ return; }",
"  var w=parseFloat(svg.getAttribute('width')), h=parseFloat(svg.getAttribute('height'));",
"  if(w&&h){ svg.setAttribute('viewBox','0 0 '+w+' '+h); svg.removeAttribute('width'); svg.removeAttribute('height'); }",
"  svg.setAttribute('preserveAspectRatio','none'); svg.setAttribute('shape-rendering','crispEdges');",
"  target.appendChild(svg);",
"}",
"async function printReceipt(){await document.fonts.ready;await Promise.all([].slice.call(document.images).filter(function(i){return !i.hidden}).map(function(i){return i.decode().catch(function(){})}));window.print()}",
"window.onload=function(){ var go=function(){ setReceiptData(__DATA__); setTimeout(printReceipt,350); }; (document.fonts&&document.fonts.load?Promise.all([document.fonts.load('700 16px PT Bold Heading'),document.fonts.load('700 16px DTP Naskh S')]).catch(function(){}):Promise.resolve()).then(go); };"
].join("\n");

