function _rcLoadLogo(){
  return new Promise(function(res){
    var m=RECEIPT_MAIN.match(/src="(data:[^"]+)"/); if(!m){ res(null); return; }
    var im=new Image(); im.onload=function(){ res(im); }; im.onerror=function(){ res(null); }; im.src=m[1];
  });
}
// Draw `text` centered at (cx, top-of-line-box centre cy); shrinks / wraps to fit maxW (mm).
function _rcFit(ctx,text,font,maxW,ppm,ltr){
  var fam=font.family||'Tahoma, Arial, sans-serif', size=font.size*ppm, wt=font.weight>=600?'bold':'normal';
  function setF(s){ ctx.font=wt+' '+s+'px '+fam; }
  setF(size);
  var avail=maxW*ppm, w=ctx.measureText(text).width;
  if(w<=avail) return {lines:[text],size:size};
  var k=Math.max(0.6,avail/w); setF(size*k);
  if(ctx.measureText(text).width<=avail) return {lines:[text],size:size*k};
  // two lines at 75%
  var s2=size*0.75; setF(s2); var words=text.split(/\s+/), l1='', l2='', i=0;
  for(;i<words.length;i++){ var t=(l1?l1+' ':'')+words[i]; if(ctx.measureText(t).width<=avail||!l1) l1=t; else break; }
  l2=words.slice(i).join(' ');
  var wmax=Math.max(ctx.measureText(l1).width,ctx.measureText(l2).width);
  if(wmax>avail) s2=s2*avail/wmax;
  return {lines:l2?[l1,l2]:[l1],size:s2};
}
function _rcDrawText(ctx,text,cx,cy,font,maxW,ppm,ltr,color){
  var fit=_rcFit(ctx,text,font,maxW,ppm,ltr), fam=font.family||'Tahoma, Arial, sans-serif', wt=font.weight>=600?'bold':'normal';
  ctx.font=wt+' '+fit.size+'px '+fam; ctx.fillStyle=color||'#111'; ctx.textAlign='center'; ctx.textBaseline='alphabetic';
  try{ ctx.direction=ltr?'ltr':'rtl'; }catch(e){}
  var lh=fit.size*(fit.lines.length>1?1.15:1.0);
  var m=ctx.measureText('Mهح'), asc=m.fontBoundingBoxAscent||fit.size*0.9, dsc=m.fontBoundingBoxDescent||fit.size*0.2;
  var total=(asc+dsc)+(fit.lines.length-1)*lh, top=cy*ppm-total/2;
  fit.lines.forEach(function(line,i){ ctx.fillText(line,cx*ppm,top+asc+i*lh); });
}
async function renderReceiptCanvas(data,ppm){
  ppm=ppm||10; data=data||{};
  var L=RECEIPT_LAYOUT, cv=document.createElement('canvas');
  cv.width=Math.round(L.sheet.w*ppm); cv.height=Math.round(L.sheet.h*ppm);
  var ctx=cv.getContext('2d');
  ctx.fillStyle='#fff'; ctx.fillRect(0,0,cv.width,cv.height);
  try{ var _pf=new FontFace('PT Bold Heading','url(data:font/woff;base64,'+RECEIPT_FONT_B64+')',{weight:'700'}); await _pf.load(); document.fonts.add(_pf); }catch(e){}
  try{ var _pf2=new FontFace('DTP Naskh S','url(data:font/woff;base64,'+RECEIPT_FONT2_B64+')',{weight:'400'}); await _pf2.load(); document.fonts.add(_pf2); }catch(e){}
  try{ await document.fonts.ready; }catch(e){}
  var logo=await _rcLoadLogo();
  // boxes: fills first, then borders (z-order: frame, table cells, bag)
  L.boxes.slice().sort(function(a,b){return a.z-b.z;}).forEach(function(b){
    var X=b.x*ppm,Y=b.y*ppm,W=b.w*ppm,H=b.h*ppm;
    if(b.bg&&!/rgba\(0, 0, 0, 0\)|transparent/.test(b.bg)){ ctx.fillStyle=b.bg; ctx.fillRect(X,Y,W,H); }
    var e=b.edges, k=b.collapse?0.5:1;
    function strip(side,x,y,w,h){ var bw=e[side][0]; if(!bw) return; ctx.fillStyle=e[side][1]; ctx.fillRect(x,y,w,h); }
    var t=e.top[0]*ppm*k, r=e.right[0]*ppm*k, bt=e.bottom[0]*ppm*k, l=e.left[0]*ppm*k;
    if(e.top[0])    strip('top',X,Y,W,t);
    if(e.bottom[0]) strip('bottom',X,Y+H-bt,W,bt);
    if(e.left[0])   strip('left',X,Y,l,H);
    if(e.right[0])  strip('right',X+W-r,Y,r,H);
  });
  if(logo){ var lr=L.logo, s=Math.min(lr.w/logo.naturalWidth,lr.h/logo.naturalHeight), w=logo.naturalWidth*s, h=logo.naturalHeight*s;
    ctx.drawImage(logo,(lr.x+(lr.w-w)/2)*ppm,(lr.y+(lr.h-h)/2)*ppm,w*ppm,h*ppm); }
  L.texts.forEach(function(t){ if(t.text==='رقم البطاقة الوطنية:'&&data.identityLabel) t=Object.assign({},t,{text:data.identityLabel}); _rcDrawText(ctx,t.text,t.x+t.w/2,t.y+t.h/2,t.font,t.w+2,ppm,t.ltr,t.font.color); });
  L.fields.forEach(function(f){
    var v=data[f.name]; v=(v===undefined||v===null)?'':String(v); if(!v) return;
    if(f.name==='barcodeValue'){ _rcDrawText(ctx,v,f.x+f.w/2,L.barcodeSlot.y+L.barcodeSlot.h+3.4,f.font,f.w,ppm,true,f.font.color); return; }
    _rcDrawText(ctx,v,f.x+f.w/2,f.y+f.h/2,f.font,f.w-2*Math.max(f.pad,1),ppm,f.ltr,f.font.color);
  });
  // The app's own barcode (JsBarcode, CODE128, value = donor number) drawn with a whole-pixel bar width.
  var bv=String(data.barcodeValue===undefined||data.barcodeValue===null?'':data.barcodeValue);
  var JB=window.JsBarcode||(window.parent&&window.parent.JsBarcode);
  if(bv&&JB){
    try{
      var slot=L.barcodeSlot, probe=document.createElement('canvas');
      JB(probe,bv,{format:'CODE128',displayValue:false,height:10,width:1,margin:0});
      var mod=Math.max(1,Math.floor(slot.w*ppm/probe.width));
      var bc=document.createElement('canvas');
      JB(bc,bv,{format:'CODE128',displayValue:false,height:Math.round(slot.h*ppm),width:mod,margin:0});
      ctx.imageSmoothingEnabled=false;
      ctx.drawImage(bc,Math.round(slot.x*ppm),Math.round(slot.y*ppm),Math.round(slot.w*ppm),Math.round(slot.h*ppm));
    }catch(e){ console.log('barcode draw failed',e); }
  }
  return cv;
}
async function receiptToPdfBlob(data){
  var cv=await renderReceiptCanvas(data,10);
  var jsPDF=window.jspdf.jsPDF;
  var doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a5',compress:true});
  doc.addImage(cv.toDataURL('image/jpeg',0.95),'JPEG',1.05,0.5,207.9,147);
  return doc.output('blob');
}
